<script setup lang="ts">
import { nextTick, onMounted, onUnmounted, ref } from 'vue'
import { AutoOnOff, createInstrumentSettingsModel, createStaffSettingsModel, createSystemObjectsLayerSettingsModel, layoutPanelPartNames, LayoutPanelItemType, type AbstractLayoutPanelTreeItem } from '../../../src/index'
import { ICON_CODES } from '../../actions/uiactiondata'
import { askInstrument } from '../../dialogs/selectinstrumentstate'
import { showMessage } from '../../components/MessageBox.vue'
import type { PartTreeItem } from '../../../src/index'
import { qtrc } from '../../i18n'
import { currentMasterScore } from '../../scoreview'
import { replacePartInstrument, scoreChanged } from '../editbridge'
const props=defineProps<{item:AbstractLayoutPanelTreeItem;anchor:DOMRect}>()
const emit=defineEmits<{close:[]}>()
const root=ref<HTMLElement|null>(null), version=ref(0)
const viewportWidth=window.innerWidth, viewportHeight=window.innerHeight
const type=props.item.type()
const instrument=type===LayoutPanelItemType.PART?createInstrumentSettingsModel(props.item.score(),props.item.id()):null
const staff=type===LayoutPanelItemType.STAFF?createStaffSettingsModel(props.item.score(),props.item.id()):null
const system=type===LayoutPanelItemType.SYSTEM_OBJECTS_LAYER?createSystemObjectsLayerSettingsModel(props.item.score(),props.item.id()):null
const name=ref(instrument?.instrumentName() ?? ''), abbreviation=ref(instrument?.abbreviature() ?? '')
const tr=(text:string)=>qtrc(instrument?'layoutpanel/instrumentsettingspopup':'layoutpanel/staffsettingspopup',text)
function change(fn:()=>void) {fn();scoreChanged();version.value++}
function commit() {if(instrument){if(name.value!==instrument.instrumentName())change(()=>instrument!.setInstrumentName(name.value));if(abbreviation.value!==instrument.abbreviature())change(()=>instrument!.setAbbreviature(abbreviation.value))}}
function close(){commit();emit('close')}
function outside(e:PointerEvent){if(!root.value?.contains(e.target as Node))close()}
onMounted(()=>{void nextTick(()=>root.value?.querySelector<HTMLElement>('input')?.focus());document.addEventListener('pointerdown',outside,true)})
onUnmounted(()=>document.removeEventListener('pointerdown',outside,true))
async function replace() {const id=props.item.id();close();const template=await askInstrument();const score=currentMasterScore();if(template&&score&&replacePartInstrument(score,id,template))scoreChanged()}
async function resetFormatting() { const item=props.item as PartTreeItem; close(); if(await showMessage(qtrc('layoutpanel','Are you sure you want to reset all formatting?'),qtrc('layoutpanel','This action can not be undone'),['no','yes'])==='yes') item.resetAllFormatting() }
</script>
<template><div ref="root" class="layout-settings-popup" :class="{'staff-settings':staff,'system-objects-settings':system}" role="dialog" :aria-label="qtrc('layoutpanel','Settings')" :style="{left:`${Math.max(4,Math.min(anchor.left,viewportWidth-268))}px`,top:`${anchor.bottom+4}px`,maxHeight:`${Math.max(160,viewportHeight-anchor.bottom-12)}px`}" @click.stop @keydown.esc.stop="close" :data-version="version">
  <template v-if="instrument"><label class="field"><span>{{ instrument.isMainScore() ? tr('Name on main score') : tr('Name on part score') }}</span><input v-model="name" type="text" class="instrument-name" :aria-label="instrument.isMainScore() ? tr('Name on main score') : tr('Name on part score')" @blur="commit" @keydown.enter.prevent="commit" /></label><label class="field"><span>{{ tr('Abbreviated name') }}</span><input v-model="abbreviation" type="text" class="instrument-abbreviature" :aria-label="tr('Abbreviated name')" @blur="commit" @keydown.enter.prevent="commit" /></label><hr class="separator" /><div class="field" role="radiogroup" :aria-label="tr('Hide empty staves')"><span class="bold">{{ tr('Hide empty staves') }}</span><label v-for="[value,text] in [[AutoOnOff.AUTO,'Auto'],[AutoOnOff.ON,'Always hide'],[AutoOnOff.OFF,'Never hide']] as const" :key="value" class="check"><input type="radio" name="instrument-hide-when-empty" :checked="instrument.hideWhenEmpty()===value" @change="change(()=>instrument!.setHideWhenEmpty(value))" />{{ tr(text) }}</label><label v-if="instrument.hasMultipleStaves()" class="check" :class="{disabled:instrument.hideWhenEmpty()===AutoOnOff.OFF}"><input type="checkbox" :checked="!instrument!.hideStavesWhenIndividuallyEmpty()" :disabled="instrument.hideWhenEmpty()===AutoOnOff.OFF" @change="change(()=>instrument!.setHideStavesWhenIndividuallyEmpty(!instrument!.hideStavesWhenIndividuallyEmpty()))" />{{ tr('Only hide staves on a system if the entire instrument is empty') }}</label></div><template v-if="layoutPanelPartNames(item)"><hr class="separator" /><button v-if="instrument.isMainScore()" type="button" class="secondary replace-instrument" @click="replace">{{ tr('Replace instrument') }}</button><button v-else type="button" class="secondary reset-formatting" @click="resetFormatting">{{ tr('Reset all formatting') }}</button></template></template>
  <template v-else-if="system"><span class="bold">{{ qtrc('layoutpanel','Display at this position on the score') }}</span><div class="field"><button v-for="(g,i) in system.groups()" :key="i" type="button" class="visibility-box" :aria-pressed="g.isGroupVisible" @click="change(()=>system!.setSystemObjectsGroupVisible(i,!g.isGroupVisible))"><span class="tool-icon" aria-hidden="true">{{ String.fromCodePoint(ICON_CODES[g.isGroupVisible?'EYE_OPEN':'EYE_CLOSED']) }}</span><span>{{ g.title }}</span></button></div></template>
  <template v-else-if="staff"><label class="field"><span class="bold">{{ tr('Staff type') }}</span><select :value="staff.staffType()" :disabled="staff.allStaffTypes().length<=1" @change="change(()=>staff!.setStaffType(Number(($event.target as HTMLSelectElement).value)))"><option v-for="t in staff.allStaffTypes()" :key="t.value" :value="t.value">{{ t.text }}</option></select></label><template v-if="!staff.isMainScore()"><hr class="separator" /><div class="field"><span>{{ tr('Voices visible in the score') }}</span><div class="voices"><label v-for="(v,i) in staff.voices()" :key="i" class="check"><input type="checkbox" :checked="v.isVoiceVisible" @change="change(()=>staff!.setVoiceVisible(i,!v.isVoiceVisible))" />{{ v.title }}</label></div></div></template><hr class="separator" /><label class="check"><input type="checkbox" :checked="staff.isSmallStaff()" @change="change(()=>staff!.setIsSmallStaff(!staff!.isSmallStaff()))" />{{ tr('Small staff') }}</label><label class="check"><input type="checkbox" :checked="staff.cutawayEnabled()" @change="change(()=>staff!.setCutawayEnabled(!staff!.cutawayEnabled()))" />{{ tr('Hide all measures that do not contain notation (cutaway)') }}</label><hr class="separator" /><div class="field" role="radiogroup" :aria-label="tr('Hide empty staves')"><span class="bold">{{ tr('Hide empty staves') }}</span><label v-for="[value,text] in [[AutoOnOff.AUTO,'Follow instrument'],[AutoOnOff.ON,'Always hide'],[AutoOnOff.OFF,'Never hide']] as const" :key="value" class="check"><input type="radio" name="hide-when-empty" :checked="staff.hideWhenEmpty()===value" @change="change(()=>staff!.setHideWhenEmpty(value))" />{{ tr(text) }}</label><label class="check"><input type="checkbox" :checked="staff.showIfEntireSystemEmpty()" @change="change(()=>staff!.setShowIfEntireSystemEmpty(!staff!.showIfEntireSystemEmpty()))" />{{ tr('If the entire system is empty, show this staff') }}</label></div><hr class="separator" /><button type="button" class="secondary create-linked-staff" @click="change(()=>staff!.createLinkedStaff());close()">{{ tr('Create a linked staff') }}</button><span class="hint">{{ tr('Linked staves contain identical notation (e.g. for guitar tablature)') }}</span></template>
</div></template>
